from pathlib import Path
import json,csv,hashlib,datetime
R=Path(__file__).resolve().parents[1];D=R/'data/raw/observatory-v7';rows=[]
def add(sid,dataset,url,date,res,crs,license,files,script,use,limits):
 if isinstance(files,Path):files=[files]
 rows.append({'source_id':sid,'Dataset':dataset,'URL_DOI':url,'download_time_utc':datetime.datetime.fromtimestamp(max(p.stat().st_mtime for p in files),datetime.timezone.utc).isoformat(),'observation_date':date,'resolution':res,'CRS':crs,'license':license,'raw_files':';'.join(str(p.relative_to(R)).replace('\\','/') for p in files),'raw_file_sha256':';'.join(hashlib.sha256(p.read_bytes()).hexdigest() for p in files),'processing_script':script,'permitted_claim':use,'limitations':limits})
add('cop-dem-glo30-aws-2022','Copernicus DEM GLO-30 public AWS COG','https://registry.opendata.aws/copernicus-dem/','2010–2015 acquisition; AWS object last-modified 2022-05-09','nominal 30m; native 1 arc-second','EPSG:4326; EGM2008 height; derived EPSG:32646','Copernicus DEM free license; © DLR e.V. 2010–2014; © Airbus Defence and Space GmbH 2014–2018; provided under COPERNICUS by EU/ESA',D/'cop-dem-glo30-native.tif','scripts/acquire_v7_public.py; scripts/process_v7_public.py','Static DSM terrain statistics','SHA is the native-grid downloaded window, not the entire remote source tile. Not GEE 2024_1; not field DTM or erosion differencing.')
for y,v in [(2020,'v100'),(2021,'v200')]:add(f'worldcover-{y}',f'ESA WorldCover {y} {v}',f'https://developers.google.com/earth-engine/datasets/catalog/ESA_WorldCover_{v}',str(y),'nominal 10m; native 0.3 arc-second','EPSG:4326; derived EPSG:32646 10m','CC-BY-4.0',D/f'worldcover-{y}-native.tif','scripts/acquire_v7_public.py; scripts/process_v7_public.py','Classification shares within fixed original 2022 footprint','Native-window SHA. Different product algorithm versions; not attributed vegetation change or carbon loss.')
add('osm-beiluhe-20261018','OpenStreetMap Overpass way records','https://overpass-api.de/api/interpreter','2026-10-18T05:34:06Z snapshot','vector; variable precision','EPSG:4326; distance EPSG:32646','ODbL-1.0',D/'osm-25000m.json','scripts/acquire_v7_public.py; scripts/process_v7_public.py','Current mapped facility proximity and OSM-way counts','Not historical 2020 survey; incomplete mapping; straight separation is not runout or risk probability.')
for sid,f,model,res,var in [('openmeteo-era5land-native-temperature','era5-land-native-daily.json','ERA5-Land','0.1 degree','temperature'),('era5-precipitation','era5-precip-native-daily.json','ERA5','0.25 degree','precipitation')]:add(sid,model+' via Open-Meteo daily archive','https://open-meteo.com/en/docs/historical-weather-api','2019-01-01/2021-12-31',res,'geographic grid','CC-BY-4.0',D/f,'scripts/acquire_v7_climate.py; scripts/process_v7_public.py','Regional monthly '+var+' background','Downscaling disabled; not station observations or direct GEE monthly asset; no event-cause attribution.')
add('openmeteo-era5land-native-temperature+era5-precipitation','ERA5-Land temperature + ERA5 precipitation composite','https://open-meteo.com/en/docs/historical-weather-api','2019–2021','temperature 0.1 degree; precipitation 0.25 degree','geographic grids','CC-BY-4.0',[D/'era5-land-native-daily.json',D/'era5-precip-native-daily.json'],'scripts/process_v7_public.py','Separate-variable calendar-month summaries','Variable resolutions differ. ERA5-Land precipitation was unavailable, not imputed as zero.')
add('xia-annual-10928346','Xia et al. annual inventory','https://zenodo.org/records/10928346','2016–2022','interpreted vector polygons','EPSG:4326 export; calculations EPSG:32646','CC-BY-4.0',[R/f'data/raw/QTP_RTS_{y}.{ext}' for y in range(2016,2023) for ext in ['shp','shx','dbf','prj','cpg']],'scripts/process_v7_public.py','Source attribute area, projected geometry area, set-difference areas','Hashes refer to retained original SHP/SHX/DBF/PRJ/CPG files. Boundary IDs are source-specific; not independent onset truth.')
add('yang-8103939','Yang et al. Beiluhe inventory','https://zenodo.org/records/8103939','nine periods through 2021; key layer 2018–2020','interpreted polygons','EPSG:32646','CC-BY-4.0',R/'data/raw/2008-2021RTSs.shp.zip','scripts/match_v6_inventory.py; scripts/experiment_v7.py','Cross-source overlap, activity-label audit','459 RTS records, inactive N is not a negative. Four overlapping candidates, no one-to-one match or independent onset validation.')
add('xia-expanded-21693485','Xia et al. expanded RTS inventory','https://zenodo.org/records/21693485','annual through 2024','interpreted polygons','EPSG:32646','CC-BY-4.0',R/'research/observatory-v6/raw/RTS-inventory.zip','scripts/match_v6_inventory.py','Cross-source spatial context with gap-fill flag','File access and MD5 confirmed locally. Different object grouping, overlapping sources, no independence claim.')
add('landsat-c2l2-fixed-pixel','USGS Landsat C2 Level 2 pixel extractions','https://www.usgs.gov/landsat-missions/landsat-collection-2-level-2-science-products','1995–2025','30m fixed pixel','source UTM scenes; WGS84 fixed position','USGS public data',[R/f'public/data/observatory/{key}.json' for key in ['rts-1820','rts-1938','background']],'scripts/acquire_observatory.py; scripts/process_observatory.py; scripts/experiment_v7.py','Spectral observations and public S-CCD prefix reproduction','Extracted DN/QA records retained with per-scene STAC URLs; not whole-scene source TIFF hashes. Cross-sensor harmonization not separately validated.')
for item in json.loads((R/'public/data/observatory-v7/sentinel-quality.json').read_text(encoding='utf-8')):
 f=D/(item['item']+'-SCL.tif');add(item['source_id'],'Copernicus Sentinel-2 L2A / native SCL',item['source_url'],item['observation_date'],'RGB 10m; SCL 20m','EPSG:32646; RGB view EPSG:4326','Copernicus Sentinel open data legal notice',f,'scripts/acquire_v7_sentinel.py','Quality-screened morphology reference','SCL native-window SHA, not whole remote file. Pre-2022 processing baseline, common RGB 400..4400 DN stretch; modelled SCL, not field truth; not S-CCD input.')
fields=list(rows[0]);
with (R/'data/source_registry.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
(R/'public/data/observatory-v7/source-registry.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
print('Source registry',len(rows),'entries')
